const result = (q, answer, unit, hint, solution, wrong, feedback) => ({q, answer: Math.round(answer * 100) / 100, unit, hint, solution, wrong: Math.round(wrong * 100) / 100, feedback});
const n = (s, mod, offset = 0) => Math.abs(Math.trunc(s)) % mod + offset;
export const course = {
  title:'1P-Y HO',
  intro:'Matematikk for helse- og oppvekstfag: utforsk økonomi, målinger og data i arbeidsliv og hverdag. Alle situasjoner og tall i oppgavene er fiktive. Vis beregninger, forklar valg og vurder resultatene.',
  source:'https://www.udir.no/lk20/mat08-01/kompetansemaal-og-vurdering/kv29?lang=nob',
  chapters:[
    {
      id:'prosent',title:'Prosent og endring',summary:'Bruk andeler, prosentpoeng og vekstfaktor.',
      theory:['Prosent er hundredeler. Delen er helheten multiplisert med prosentandelen som desimaltall; prosentandelen er delen delt på helheten multiplisert med 100.','Prosentpoeng er differansen mellom to prosentandeler. Relativ endring måles derimot i prosent av den opprinnelige verdien. Ved p % økning er vekstfaktoren 1 + p/100.'],
      example:['I en fiktiv barnehage sykler 18 av 60 ansatte og barn til et arrangement: 18/60 · 100 = 30 %.','Andelen øker fra 30 % til 36 %: økningen er 6 prosentpoeng, eller 6/30 · 100 = 20 % relativt.'],
      activity:'Undersøk en fiktiv gruppe på 200 personer der andelen som velger en aktivitet øker fra 25 % til 30 %. Finn antall før og etter, endring i prosentpoeng og relativ prosent. Diskuter hvordan konklusjonen endres dersom gruppestørrelsen også endres.',
      criteria:['Velger riktig grunnlag og viser utregning.','Skiller prosentpoeng og relativ endring.','Forklarer forutsetningen om gruppestørrelse.'],
      model:'25 % av 200 er 50 og 30 % av 200 er 60. Økningen er 5 prosentpoeng og 5/25 · 100 = 20 %. Antallsendringen forutsetter 200 personer begge ganger.',
      teacher:'Forkunnskaper: brøk og desimaltall. Vanlig feil er å bruke ny verdi som grunnlag for relativ endring. Spør hva nevneren betyr.',
      goals:['Bruke prosentregning i praktiske situasjoner og begrunne valg av grunnlag.'],
      task(level,seed){let p=n(seed,8,2)*5,x=n(seed,8,2)*100;if(level===0)return result(`Et fiktivt utstyrslager inneholder ${x} varer. ${p} % brukes. Hvor mange varer er det?`,x*p/100,'varer','Gjør prosent til desimaltall.',`${x} · ${p}/100 = ${x*p/100}.`,x+p,'Multipliser andelen med hele antallet.');if(level===1){let a=n(seed,15,20),d=n(seed,8,2);return result(`Andelen øker fra ${a} % til ${a+d} %. Hvor mange prosentpoeng er økningen?`,d,'prosentpoeng','Trekk andelene fra hverandre.',`${a+d} − ${a} = ${d} prosentpoeng.`,100*d/a,'Dette er relativ prosentvis endring.');}return result(`En vare koster ${x} kr og øker ${p} %. Hva er ny pris?`,x*(1+p/100),'kr','Bruk vekstfaktor 1 + p/100.',`${x} · ${1+p/100} = ${x*(1+p/100)} kr.`,x*p/100,'Dette er økningen, ikke ny pris.');}
    },
    {
      id:'lan',title:'Personlig økonomi, lån og kreditt',summary:'Beregn renter og sammenlign samlede kostnader.',
      theory:['Et budsjett viser forventede inntekter og utgifter. Differansen er et overskudd eller underskudd; uforutsette utgifter kan gjøre resultatet usikkert.','Renter er prisen for å låne penger. For ett år med uendret gjeld er renten gjeld · rentesats. Effektiv rente tar også hensyn til gebyrer og betalingsmønster; sammenlign derfor total betaling og vilkår, ikke bare nominell rente.'],
      example:['Et fiktivt lån på 10 000 kr har 8 % årlig rente. Med uendret gjeld i ett år er renten 10 000 · 0,08 = 800 kr.','Med et gebyr på 200 kr blir samlet kostnad 1000 kr og tilbakebetaling 11 000 kr. Eksemplet forutsetter ingen avdrag underveis.'],
      activity:'Sammenlign to fiktive lån på 10 000 kr som tilbakebetales etter ett år: A har 8 % rente og 200 kr gebyr, B har 7 % rente og 400 kr gebyr. Finn total betaling. Drøft hva som endres dersom gjelden betales ned underveis eller betalingen blir forsinket.',
      criteria:['Skiller lånebeløp, renter og gebyr.','Oppgir antakelser og sammenligner totalbeløp.','Drøfter usikkerhet og nedbetaling.'],
      model:'A koster 800 + 200 = 1000 kr og B koster 700 + 400 = 1100 kr. Totalt betales henholdsvis 11 000 og 11 100 kr. Renteberegningen bygger på uendret gjeld hele året.',
      teacher:'Forkunnskaper: prosent. Feil: se bare på rentesatsen og overse gebyrer. Spør når gjelden endres og hva betalingene faktisk summerer seg til.',
      goals:['Planlegge personlig økonomi og undersøke lån og kreditt med ulike forutsetninger.','Vurdere konsekvensene av kredittkortbruk.'],
      task(level,seed){let x=n(seed,8,2)*1000,p=n(seed,8,3);if(level===0)return result(`En fiktiv gjeld på ${x} kr står uendret i ett år med ${p} % rente. Hvor mye er renten?`,x*p/100,'kr','Multipliser gjelden med renten som desimaltall.',`${x} · ${p}/100 = ${x*p/100} kr.`,x*p,'Del prosentsatsen på 100.');if(level===1){let fee=n(seed,5,1)*100;return result(`Et lån på ${x} kr har ${p} % rente i ett år og ${fee} kr i gebyr. Gjelden er uendret til tilbakebetaling. Hva betales totalt?`,x+x*p/100+fee,'kr','Legg lånet, renten og gebyret sammen.',`${x} + ${x*p/100} + ${fee} = ${x+x*p/100+fee} kr.`,x*p/100+fee,'Dette er kostnaden; selve lånet må også betales.');}let inc=n(seed,8,20)*1000,cost=n(seed,8,10)*1000;return result(`Fiktiv nettoinntekt er ${inc} kr per måned og utgiftene ${cost} kr. Hvor stort er overskuddet?`,inc-cost,'kr','Trekk utgiftene fra inntekten.',`${inc} − ${cost} = ${inc-cost} kr.`,inc+cost,'Overskudd er differansen, ikke summen.');}
    },
    {
      id:'formler',title:'Formler i arbeidslivet',summary:'Sett inn, tolk og omform enkle formler.',
      theory:['En formel beskriver en sammenheng mellom størrelser. Definer symboler og enheter før innsetting, og bruk regnerekkefølgen.','En ukjent isoleres ved å gjøre samme operasjon på begge sider. Kontroller ved å sette svaret inn i den opprinnelige formelen. Modellen gjelder bare når forutsetningene er oppfylt.'],
      example:['En fiktiv aktivitet koster K = 150 + 40n kroner for n deltakere. For 10 deltakere er K = 150 + 40 · 10 = 550 kr.','Når K = 550, er n = (550 − 150)/40 = 10. Kontroll: 150 + 40 · 10 = 550.'],
      activity:'En utflukt har kostnaden K = 600 + 75n kroner. Lag tabell for 0, 5, 10 og 20 deltakere og finn hvor mange som gir 1800 kr. Forklar hva fastleddet og satsen betyr, og vurder om modellen passer for svært store grupper.',
      criteria:['Definerer variabler og enheter.','Viser innsetting, omforming og kontroll.','Vurderer modellens gyldighet.'],
      model:'Kostnadene er 600, 975, 1350 og 2100 kr. (1800 − 600)/75 = 16 deltakere. Modellen forutsetter fast pris per deltaker og uendret fastkostnad.',
      teacher:'Forkunnskaper: regnerekkefølge og likninger. Feil: dele totalbeløpet på satsen før fastleddet trekkes fra. Spør hva null deltakere betyr.',
      goals:['Tolke og bruke formler knyttet til praktiske situasjoner.'],
      task(level,seed){let a=n(seed,8,2)*10,b=n(seed,5,1)*100,x=n(seed,8,2);if(level===0)return result(`En aktivitet koster K = ${a}n kroner. Finn K når n = ${x}.`,a*x,'kr','Sett inn antallet.',`${a} · ${x} = ${a*x} kr.`,a+x,'Multipliser satsen med antallet.');if(level===1)return result(`K = ${b} + ${a}n. Finn K når n = ${x}.`,b+a*x,'kr','Legg fastkostnaden til den variable kostnaden.',`${b} + ${a} · ${x} = ${b+a*x} kr.`,a*x,'Fastkostnaden mangler.');return result(`K = ${b} + ${a}n. Finn n når K = ${b+a*x} kr.`,x,'deltakere','Trekk fra fastleddet og del på satsen.',`n = (${b+a*x} − ${b})/${a} = ${x}.`,(b+a*x)/a,'Trekk fra fastleddet først.');}
    },
    {
      id:'enheter',title:'Sammensatte måleenheter',summary:'Bruk enhetspris, tidsbruk og forbruk.',
      theory:['En sammensatt måleenhet viser forholdet mellom to størrelser. Kr/kg betyr kroner per kilogram, og minutter per deltaker beskriver tidsbruk delt på antall deltakere.','Enhetene hjelper oss kontrollere beregningen: kg · kr/kg = kr. Ved omregning er 1000 g = 1 kg og 60 min = 1 time. Gjennomsnitt beskriver ikke nødvendigvis hver enkelt observasjon.'],
      example:['En pakke på 2,5 kg koster 100 kr. Enhetsprisen er 100/2,5 = 40 kr/kg.','Kontroll: 2,5 kg · 40 kr/kg = 100 kr.'],
      activity:'Sammenlign fiktive pakker på 750 g til 45 kr og 1,2 kg til 66 kr. Beregn kr/kg, og finn kostnaden for 3 kg med hver enhetspris. Drøft hele pakker, svinn og lagring som forhold som kan påvirke valget.',
      criteria:['Omregner gram til kilogram.','Viser beregning med enheter.','Drøfter forhold som enhetsprisen ikke fanger opp.'],
      model:'750 g = 0,75 kg. Prisene er 45/0,75 = 60 kr/kg og 66/1,2 = 55 kr/kg. Tre kg tilsvarer henholdsvis 180 og 165 kr ved ubegrenset deling; faktiske innkjøp krever hele pakker.',
      teacher:'Forkunnskaper: divisjon og måleenheter. Feil: bruke gram som kilogram. Spør om lavest pris per kg alltid gir lavest faktisk utgift.',
      goals:['Tolke og bruke sammensatte måleenheter i praktiske sammenhenger.'],
      task(level,seed){let kg=n(seed,5,2),rate=n(seed,8,3)*10;if(level===0)return result(`En fiktiv vare koster ${rate} kr/kg. Hva koster ${kg} kg?`,kg*rate,'kr','Multipliser vekt med pris per kg.',`${kg} · ${rate} = ${kg*rate} kr.`,kg+rate,'Multipliser størrelsene.');if(level===1)return result(`${kg} kg koster ${kg*rate} kr. Hva er enhetsprisen?`,rate,'kr/kg','Del prisen på vekten.',`${kg*rate}/${kg} = ${rate} kr/kg.`,kg*rate,'Dette er prisen for hele pakken.');let minutes=n(seed,6,2)*30,people=n(seed,6,2);return result(`En aktivitet varer ${minutes} minutter for ${people} deltakere. Hva er gjennomsnittlig tid per deltaker når samlet tid fordeles likt? Avrund til to desimaler.`,minutes/people,'min/deltaker','Del samlet tid på antall deltakere.',`${minutes}/${people} = ${(minutes/people).toFixed(2)} min/deltaker.`,minutes*people,'Del tiden på antall deltakere.');}
    },
    {
      id:'data',title:'Praktiske data og statistikk',summary:'Samle, presenter og vurder data kritisk.',
      theory:['Et datasett kan oppsummeres med gjennomsnitt, median og variasjonsbredde. Gjennomsnittet er summen delt på antallet; medianen er den midterste verdien etter sortering, eller gjennomsnittet av de to midterste.','Målemetode, utvalg og frafall påvirker hva dataene kan si. En sammenheng i et lite eller skjevt utvalg viser ikke nødvendigvis en årsakssammenheng eller forholdene i hele befolkningen.'],
      example:['Fiktive ventetider i minutter: 4, 5, 5, 6, 15.','Gjennomsnittet er 35/5 = 7 minutter, medianen er 5 og variasjonsbredden er 15 − 4 = 11 minutter. Den høye verdien trekker gjennomsnittet opp.'],
      activity:['Bruk de fiktive ventetidene 4, 5, 5, 6 og 15 minutter. Lag et passende diagram, beregn gjennomsnitt, median og variasjonsbredde. Bytt 15 til 25 og sammenlign. Beskriv hvilke opplysninger om innsamlingen som trengs før resultatene kan generaliseres.','Gjennomfør deretter en egen enkel måling i praksis eller klasserommet, for eksempel tid brukt til å sortere utstyr. Samle minst fem målinger uten personopplysninger, gjør overslag før du regner, og presenter resultatet.'],
      dataset:{title:'Fiktive ventetider',headers:['Observasjon','Ventetid (min)'],rows:[[1,4],[2,5],[3,5],[4,6],[5,15]]},
      criteria:['Velger passende diagram og merker akser og enheter.','Beregner og tolker sentralmål og spredning.','Vurderer utvalg og begrensninger.'],
      model:'Med 25 i stedet for 15 blir gjennomsnittet 45/5 = 9 minutter, medianen er fortsatt 5 og variasjonsbredden 21. Vi vet ikke hvordan tidspunktene ble valgt eller hvor representative de er.',
      teacher:'Forkunnskaper: divisjon og sortering. Feil: finne median uten å sortere eller anta at gjennomsnittet beskriver alle. Spør hva en ekstremverdi gjør.',
      goals:['Samle, bearbeide og presentere data og vurdere datagrunnlag.'],
      task(level,seed){let a=n(seed,8,2);if(level===0)return result(`Fiktive ventetider er ${a}, ${a+2} og ${a+4} minutter. Finn gjennomsnittet.`,a+2,'min','Legg sammen og del på tre.',`(${a} + ${a+2} + ${a+4})/3 = ${a+2} min.`,3*a+6,'Del summen på antall observasjoner.');if(level===1)return result(`Fiktive observasjoner er ${a+4}, ${a}, ${a+2}, ${a+1}, ${a+8}. Finn medianen.`,a+2,'','Sorter observasjonene først.',`Sortert: ${a}, ${a+1}, ${a+2}, ${a+4}, ${a+8}. Medianen er ${a+2}.`,a+4,'Medianen er den midterste i sortert rekkefølge.');return result(`Minste fiktive observasjon er ${a} og største er ${a+9}. Finn variasjonsbredden.`,9,'','Trekk minste verdi fra største.',`${a+9} − ${a} = 9.`,a+9,'Største verdi alene er ikke variasjonsbredden.');}
    },
    {
      id:'regneark',title:'Budsjett og regneark',summary:'Bygg et regneark med formler og undersøk endringer.',
      theory:['Et regneark kan skille inndata fra beregnede verdier. En formel som =B2*C2 beregner produktet i raden; =SUMMER(D2:D5) summerer et område når funksjonsnavnet støttes av programmet.','Relative cellereferanser endres når en formel kopieres. En absolutt referanse, for eksempel $B$1, holder en felles sats fast. Kontroller formler med en håndberegning og undersøk effekten av endrede forutsetninger.'],
      example:['Et aktivitetsbudsjett har 20 deltakere og 75 kr per deltaker, samt 600 kr i faste utgifter.','Formelen =20*75+600 gir 2100 kr. Hvis antallet øker til 24, blir utgiften 2400 kr.'],
      activity:'Lag et regneark for et fiktivt arrangement med antall, enhetspris, linjesum, faste utgifter og inntekter. Bruk celleformler for totalutgift og resultat. Undersøk minst to deltakerantall, kontroller én rad for hånd og beskriv hvilke utgifter som kan være utelatt.',
      dataset:{title:'Inndata for aktivitetsbudsjett',headers:['Post','Antall','Enhetspris (kr)'],rows:[['Deltakerutgift',20,75],['Fast utgift',1,600],['Inntekt',1,2500]]},
      criteria:['Inndata og beregninger er tydelig merket.','Formler gir riktige summer og kan kopieres.','Alternativer og usikkerhet drøftes.'],
      model:'Ved 20 deltakere, 75 kr per deltaker og 600 kr fast utgift er kostnaden 2100 kr. Med inntekt 2500 kr er resultatet 400 kr. Ved 24 deltakere blir kostnaden 2400 kr hvis satsene er uendret.',
      teacher:'Forkunnskaper: prosent, regnerekkefølge og regneark. Feil: skrive faste resultater i stedet for formler eller inkludere sumcellen i sitt eget område. Spør hvordan arket reagerer når en forutsetning endres.',
      goals:['Bruke digitale verktøy til å planlegge og utforske økonomiske situasjoner.'],
      task(level,seed){let count=n(seed,8,2),price=n(seed,8,2)*10,fixed=n(seed,6,1)*100;if(level===0)return result(`I et regneark er antall ${count} og pris ${price} kr per enhet. Hva blir linjesummen?`,count*price,'kr','Multipliser antall med pris.',`${count} · ${price} = ${count*price} kr.`,count+price,'Linjesummen er produktet.');if(level===1)return result(`Et budsjett har variable utgifter ${count*price} kr og faste utgifter ${fixed} kr. Finn totalutgiften.`,count*price+fixed,'kr','Legg sammen begge utgiftstypene.',`${count*price} + ${fixed} = ${count*price+fixed} kr.`,count*price,'Den faste utgiften mangler.');let income=count*price+fixed+300;return result(`Inntekten er ${income} kr, og utgiftene er ${count*price} kr og ${fixed} kr. Hva er resultatet?`,300,'kr','Trekk alle utgifter fra inntekten.',`${income} − ${count*price} − ${fixed} = 300 kr.`,income-count*price,'Husk begge utgiftspostene.');}
    },
    {
      id:'innkjop',title:'Innkjøp og tilbud',summary:'Sammenlign tilbud ut fra samlet pris og vilkår.',
      theory:['Ved sammenligning av tilbud må antall, enhetspris, faste gebyrer og eventuelle rabatter regnes med. Sammenlign samme mengde og kontroller om prisene inkluderer de samme tjenestene.','En enkel modell for et tilbud kan være K(n) = fastkostnad + enhetspris · n. Skjæringspunktet viser når to tilbud koster like mye, men kvalitet, leveringstid og hele pakker kan påvirke valget.'],
      example:['Fiktivt tilbud A: 300 kr i levering og 40 kr per enhet. B: 100 kr i levering og 50 kr per enhet.','Ved 20 enheter koster begge 1100 kr. Ved 30 koster A 1500 kr og B 1600 kr.'],
      activity:'Lag et regneark som sammenligner tilbudene A = 300 + 40n og B = 100 + 50n for 0–50 enheter. Finn lik pris, sammenlign ved 10 og 30, og vurder hvordan leveringstid og bestilling i hele pakker kan påvirke avgjørelsen.',
      criteria:['Regner med både fast og variabel kostnad.','Finner og tolker lik pris.','Drøfter minst to praktiske vilkår.'],
      model:'40n + 300 = 50n + 100 gir n = 20 og pris 1100 kr. Ved 10 koster A 700 og B 600 kr; ved 30 koster A 1500 og B 1600 kr. Valget avhenger også av vilkårene.',
      teacher:'Forkunnskaper: lineære uttrykk og regneark. Feil: sammenligne bare enhetspris. Spør om samme antall, kvalitet og leveringsvilkår er lagt til grunn.',
      goals:['Sammenligne tilbud og begrunne økonomiske valg med beregninger.'],
      task(level,seed){let x=n(seed,8,2)*10,a=n(seed,5,3)*10,fee=n(seed,5,1)*100;if(level===0)return result(`Et fiktivt tilbud er ${a} kr per enhet pluss ${fee} kr i levering. Hva koster ${x} enheter?`,a*x+fee,'kr','Beregn varepris og legg til levering.',`${a} · ${x} + ${fee} = ${a*x+fee} kr.`,a*x,'Leveringsgebyret mangler.');if(level===1){let d=n(seed,5,1)*10;return result(`To tilbud koster A = ${a}n + ${fee+d*10} og B = ${a+d}n + ${fee}. Ved hvilket antall er prisene like?`,10,'enheter','Sett uttrykkene lik hverandre.',`${a}n + ${fee+d*10} = ${a+d}n + ${fee} gir n = 10.`,fee/d,'Forskjellen i fastkostnad er relevant, ikke ett gebyr alene.');}let disc=n(seed,4,1)*5;return result(`Varer koster ${x*a} kr før rabatt. Rabatten er ${disc} %. Hva betales for varene?`,x*a*(1-disc/100),'kr','Bruk nedgangsfaktor 1 − rabatt/100.',`${x*a} · ${1-disc/100} = ${x*a*(1-disc/100)} kr.`,x*a*disc/100,'Dette er rabatten, ikke beløpet etter rabatt.');}
    },
    {
      id:'velferdsteknologi',title:'Økonomi og velferdsteknologi',summary:'Modeller kostnader og vurder økonomiske og menneskelige konsekvenser.',
      theory:['En økonomisk modell kan sammenligne en investering og løpende kostnader med et alternativ. Forskjellen i løpende kostnad kan brukes til å finne et enkelt tilbakebetalingstidspunkt.','Resultatet avhenger av antakelser om brukstid, vedlikehold og besparelser. Personvern, tilgjengelighet, opplæring, trygghet og individuelle behov kan være avgjørende selv om de ikke inngår i kroner-modellen.'],
      example:['En fiktiv løsning koster 12 000 kr i innkjøp og 2000 kr per år. Et alternativ koster 5000 kr per år.','Årlig kostnadsforskjell er 3000 kr. Uten rente og andre kostnader er tilbakebetalingstiden 12 000/3000 = 4 år. Etter 4 år koster begge 20 000 kr.'],
      activity:'Sammenlign de to fiktive løsningene i eksemplet for 0–6 år i regneark. Undersøk også hva som skjer om den nye løsningen krever 3000 kr per år. Forklar hvilke kostnader og kvalitetsforhold modellen utelater, og begrunn en anbefaling.',
      criteria:['Viser formler, tabell og lik kostnad.','Undersøker endrede forutsetninger.','Vurderer både økonomiske og menneskelige forhold.'],
      model:'Kostnadene er N(t)=12000+2000t og A(t)=5000t. De er like etter 4 år. Med 3000 kr i årlig kostnad blir forskjellen 2000 kr per år og tilbakebetalingstiden 6 år. Opplæring, personvern og nytte for brukeren krever egen vurdering.',
      teacher:'Forkunnskaper: lineære modeller og økonomi. Feil: tolke tilbakebetalingstid som garanti for faktisk besparelse. Spør hvilke verdier som mangler og om løsningene gir like god nytte.',
      goals:['Modellere praktiske økonomiske valg og vurdere premisser og konsekvenser.'],
      task(level,seed){let purchase=n(seed,8,2)*1000,annual=n(seed,5,1)*500,years=n(seed,5,2);if(level===0)return result(`En fiktiv løsning koster ${purchase} kr i innkjøp og ${annual} kr per år. Finn kostnaden etter ${years} år.`,purchase+annual*years,'kr','Legg innkjøp og årlige kostnader sammen.',`${purchase} + ${years} · ${annual} = ${purchase+annual*years} kr.`,annual*years,'Innkjøpskostnaden mangler.');if(level===1){let diff=n(seed,6,2)*500;return result(`En løsning reduserer løpende kostnader med ${diff} kr per år og koster ${purchase} kr å kjøpe. Finn enkel tilbakebetalingstid uten rente.`,purchase/diff,'år','Del investeringen på årlig besparelse.',`${purchase}/${diff} = ${(purchase/diff).toFixed(2)} år.`,purchase*diff,'Del investeringen på besparelsen.');}let old=annual+1000;return result(`En ny løsning koster ${purchase} + ${annual}t kr og et alternativ ${old}t kr etter t år. Hvor mange kroner skiller kostnadene etter ${years} år hvis alternativets kostnad trekkes fra den nye løsningens?`,purchase+annual*years-old*years,'kr','Beregn begge modellene og trekk alternativet fra.',`${purchase+annual*years} − ${old*years} = ${purchase+annual*years-old*years} kr.`,purchase+annual*years,'Trekk også fra alternativets kostnad.');}
    }
  ]
};
